class Gate:
    def __init__(self):
        self.state = "closed"
    def ticket(self):
        if self.state == "closed":
            self.state = "open"
            print("ticket -> open")
        else:
            print(f"ticket ignored while {self.state}")
    def car_passed(self):
        if self.state == "open":
            self.state = "closed"
            print("car passed -> closed")
        else:
            print(f"car_passed ignored while {self.state}")
    def lock(self):
        self.state = "locked"
        print("lock -> locked")
    def unlock(self):
        if self.state == "locked":
            self.state = "closed"
            print("unlock -> closed")

g = Gate()
g.car_passed()
g.ticket()
g.car_passed()
g.lock()
g.ticket()
g.unlock()
g.ticket()
print("final:", g.state)

