class Clock:
    def __init__(self):
        self.now = 0
    def advance(self, seconds):
        self.now += seconds

class TtlCache:
    def __init__(self, clock, ttl):
        self.clock = clock
        self.ttl = ttl
        self.entries = {}
    def put(self, key, value):
        self.entries[key] = (value, self.clock.now + self.ttl)
    def get(self, key):
        value, expires = self.entries[key]
        if self.clock.now < expires:
            return f"hit: {value}"
        return "miss: expired"

clock = Clock()
c = TtlCache(clock, ttl=30)
c.put("session", "abc")
print("t=0 :", c.get("session"))
clock.advance(20)
print("t=20:", c.get("session"))
clock.advance(15)
print("t=35:", c.get("session"))

