db = {"p1": "hammer"}
db_reads = 0
cache = {}
MISSING = "<missing>"

def get_product(pid):
    global db_reads
    if pid in cache:
        return cache[pid]
    db_reads += 1
    cache[pid] = db.get(pid, MISSING)
    return cache[pid]

for _ in range(3):
    print("lookup ghost:", get_product("ghost"))
print("db reads:", db_reads)

