class VersionedDoc:
    def __init__(self, text):
        self.versions = [text]          # each entry is an immutable string
    @property
    def current(self):
        return self.versions[-1]
    def edit(self, new_text):
        self.versions.append(new_text)  # old versions untouched
        return len(self.versions) - 1
    def rollback(self, version):
        return self.versions[version]

d = VersionedDoc("Draft one.")
v1 = d.edit("Draft one, revised.")
v2 = d.edit("Final draft.")
print("current: ", d.current)
print("v0 still:", d.rollback(0))
print("v1 still:", d.rollback(1))
print("versions kept:", len(d.versions))

