class Cell:
    def __init__(self, value):
        self.value = value
        self.version = 0
    def cas(self, expected_version, new_value):
        if self.version != expected_version:
            return False
        self.value = new_value
        self.version += 1
        return True

cell = Cell(100)
my_version = cell.version          # I read version 0, value 100
cell.cas(cell.version, 105)        # a rival commits first: version -> 1
attempts = 0
while True:
    attempts += 1
    if cell.cas(my_version, cell.value + 10):
        break
    my_version = cell.version      # reload and retry with fresh eyes
print("committed:", cell.value, "| attempts:", attempts, "| version:", cell.version)

def run(locked):
    acct = {"A": 100, "B": 0, "C": 0}
    def check(a, amt):
        return acct[a] >= amt
    def debit(a, amt):
        acct[a] -= amt
    def credit(a, amt):
        acct[a] += amt
    if not locked:
        ok1 = check("A", 80)
        ok2 = check("A", 80)     # both checks see the pre-debit balance
        if ok1: debit("A", 80); credit("B", 80)
        if ok2: debit("A", 80); credit("C", 80)
    else:
        for dest in ("B", "C"):  # each transfer's check+debit+credit is one atomic trio
            if check("A", 80):
                debit("A", 80); credit(dest, 80)
    return acct

print("unlocked:", run(False))
print("locked:  ", run(True))

