class Store:
    def __init__(self):
        self._items = {}
        self.log = []
    def put(self, key, value):
        if value < 0:
            print(f"rejected: {key} cannot be negative")
            return
        self._items[key] = value
        self.log.append(f"put {key}={value}")
    def remove(self, key):
        del self._items[key]
        self.log.append(f"remove {key}")
    def snapshot(self):
        return dict(self._items)

s = Store()
s.put("apples", 5)
